<?php if(!isset($suiteReady)||!$suiteReady)return;
$profiles=suite_rows($pdo,'employment',$user,$suite['employment']);$departments=[];foreach($profiles as $r){$d=json_decode($r['data'],true);$dep=$d['department']??'';$dep=$dep?:'Not assigned';$departments[$dep]=($departments[$dep]??0)+1;}arsort($departments);
$holidays=suite_rows($pdo,'holidays',$user,$suite['holidays']);$upcoming=[];foreach($holidays as $r){$d=json_decode($r['data'],true);if($r['status']==='Published'&&($d['date']??'')>=date('Y-m-d'))$upcoming[]=['date'=>$d['date'],'title'=>$r['title']];}usort($upcoming,fn($a,$b)=>strcmp($a['date'],$b['date']));
?>
<div class="suite-dashboard"><section class="panel"><h2><?=$admin?'People by department':'My employment record'?></h2><?php foreach($departments as $label=>$n):?><div class="bar-row"><span><?=h($label)?></span><div class="bar-track"><div class="bar-fill" style="width:<?=round(100*$n/max(1,count($profiles)))?>%"></div></div><b><?=$n?></b></div><?php endforeach;if(!$profiles):?><p>No employment profiles yet.</p><?php endif?><a href="?page=employment">View profiles →</a></section><section class="panel"><h2>Upcoming holidays</h2><?php foreach(array_slice($upcoming,0,5) as $r):?><div class="upcoming"><b><?=h($r['title'])?></b><p><?=h($r['date'])?></p></div><?php endforeach;if(!$upcoming):?><p>No upcoming holidays published.</p><?php endif?><a href="?page=holidays">Holiday calendar →</a></section><section class="panel"><h2>Tasks to complete</h2><?php $tasks=suite_rows($pdo,'tasks',$user,$suite['tasks']);$count=0;foreach($tasks as $r){if($r['status']==='Completed')continue;if(++$count>5)break;$d=json_decode($r['data'],true);echo '<div class="upcoming"><b>'.h($r['title']).'</b><p>'.h($r['employee_name']).' · Due '.h($d['due']).'</p></div>';}if(!$count)echo '<p>No outstanding tasks.</p>';?><a href="?page=tasks">View tasks →</a></section><section class="panel"><h2>Document expiry reminders</h2><?php $docs=suite_rows($pdo,'documents',$user,$suite['documents']);$count=0;foreach($docs as $r){$d=json_decode($r['data'],true);if(empty($d['expires'])||$d['expires']>date('Y-m-d',strtotime('+30 days')))continue;if(++$count>5)break;echo '<div class="upcoming"><b>'.h($r['title']).'</b><p>'.h($r['employee_name']).' · '.h($d['expires']).'</p></div>';}if(!$count)echo '<p>No registered documents expire in the next 30 days.</p>';?><a href="?page=documents">View documents →</a></section></div>
